1 2  $ cp *.ko /lib/modules/$(uname -r)/extra/ $ depmod –a   4. 打包squashfs 1  $ mksquashfs squashfs-root-dir filesystem.squashfs –force-uid 0 –all-root   5. pxelinux.cfg/default 1 2 3 4  LABEL myos MENU LABEL myos kernel myos/live/vmlinuz append initrd=/myos/live/initrd.img boot=live union=overlayfs noswap edd=on nomodeset noprompt config nosplash only-ubiquity ip=frommedia vgz=791 locales=zh_CN.UTF-8 keyboard-layouts=NONE ocs_live_batch=&#34;yes&#34; fetch=tftp://192.18.0.2/myos/live/filesystem.squashfs ocs_premount=&#34;mount -t nfs 192.168.0.2:/tftpboot/myos/home/partimag /home/partimag&#34; ocs_live_run=&#34;ocs-sr -g auto -e1 auto -e2 -c -r -j2 -k1 -p reboot restoredisk ask_user ask_user&#34;
